Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
netfilter: x_tables: restrict xt_check_match/xt_check_target
 extensions for NFPROTO_ARP

Weiming Shi says:

xt_match and xt_target structs registered with NFPROTO_UNSPEC can be
loaded by any protocol family through nft_compat. When such a
match/target sets .hooks to restrict which hooks it may run on, the
bitmask uses NF_INET_* constants. This is only correct for families
whose hook layout matches NF_INET_*: IPv4, IPv6, INET, and bridge
all share the same five hooks (PRE_ROUTING ... POST_ROUTING).

ARP only has three hooks (IN=0, OUT=1, FORWARD=2) with different
semantics. Because NF_ARP_OUT == 1 == NF_INET_LOCAL_IN, the .hooks
validation silently passes for the wrong reasons, allowing matches to
run on ARP chains where the hook assumptions (e.g. state->in being
set on input hooks) do not hold. This leads to NULL pointer
dereferences; xt_devgroup is one concrete example:

 Oops: general protection fault, probably for non-canonical address 0xdffffc0000000044: 0000 [#1] SMP KASAN NOPTI
 KASAN: null-ptr-deref in range [0x0000000000000220-0x0000000000000227]
 RIP: 0010:devgroup_mt+0xff/0x350
 Call Trace:
  <TASK>
  nft_match_eval (net/netfilter/nft_compat.c:407)
  nft_do_chain (net/netfilter/nf_tables_core.c:285)
  nft_do_chain_arp (net/netfilter/nft_chain_filter.c:61)
  nf_hook_slow (net/netfilter/core.c:623)
  arp_xmit (net/ipv4/arp.c:666)
  </TASK>
 Kernel panic - not syncing: Fatal exception in interrupt

Fix it by restricting arptables to NFPROTO_ARP extensions only.
Note that arptables-legacy only supports:

- arpt_CLASSIFY
- arpt_mangle
- arpt_MARK

that provide explicit NFPROTO_ARP match/target declarations.

Fixes: 9291747f118d ("netfilter: xtables: add device group match")
Reported-by: Xiang Mei <xmei5@asu.edu>
Signed-off-by: Florian Westphal <fw@strlen.de>
Signed-off-by: Pablo Neira Ayuso <pablo@netfilter.org>

Here is the root cause:
The bug occurs because xt_match and xt_target extensions registered with NFPROTO_UNSPEC use NF_INET_* hook constants in their .hooks bitmask, but NFPROTO_ARP defines different hook constants (NF_ARP_IN, NF_ARP_OUT, NF_ARP_FORWARD) whose numeric values accidentally overlap with NF_INET_* values (e.g., NF_ARP_OUT == 1 == NF_INET_LOCAL_IN). The hook mask validation in xt_check_match() and xt_check_target() only checks bitmask overlap, not the protocol family, so these extensions are incorrectly allowed to run on ARP chains. This permits matches/targets that assume NF_INET hook semantics (e.g., state->in being set on input hooks) to execute on ARP hooks with different semantics, leading to NULL pointer dereferences such as the devgroup_mt crash.

Here is the patch:

 int xt_check_match(struct xt_mtchk_param *par,
 		   unsigned int size, u16 proto, bool inv_proto)
 {
 	int ret;

 	if (XT_ALIGN(par->match->matchsize) != size &&
 	    par->match->matchsize != -1) {
 		/*
 		 * ebt_among is exempt from centralized matchsize checking
 		 * because it uses a dynamic-size data set.
 		 */
 		pr_err_ratelimited("%s_tables: %s.%u match: invalid size %u (kernel) != (user) %u\n",
 				   xt_prefix[par->family], par->match->name,
 				   par->match->revision,
 				   XT_ALIGN(par->match->matchsize), size);
 		return -EINVAL;
 	}
 	if (par->match->table != NULL &&
 	    strcmp(par->match->table, par->table) != 0) {
 		pr_info_ratelimited("%s_tables: %s match: only valid in %s table, not %s\n",
 				    xt_prefix[par->family], par->match->name,
 				    par->match->table, par->table);
 		return -EINVAL;
 	}
+
+	/* NFPROTO_UNSPEC implies NF_INET_* hooks which do not overlap with
+	 * NF_ARP_IN,OUT,FORWARD, allow explicit extensions with NFPROTO_ARP
+	 * support.
+	 */
+	if (par->family == NFPROTO_ARP &&
+	    par->match->family != NFPROTO_ARP) {
+		pr_info_ratelimited("%s_tables: %s match: not valid for this family\n",
+				    xt_prefix[par->family], par->match->name);
+		return -EINVAL;
+	}
 	if (par->match->hooks && (par->hook_mask & ~par->match->hooks) != 0) {
 		char used[64], allow[64];

 		pr_info_ratelimited("%s_tables: %s match: used from hooks %s, but only valid from %s\n",
 				    xt_prefix[par->family], par->match->name,
 				    textify_hooks(used, sizeof(used),
 						  par->hook_mask, par->family),
 				    textify_hooks(allow, sizeof(allow),
 						  par->match->hooks,
 						  par->family));
 		return -EINVAL;
 	}
 	if (par->match->proto && (par->match->proto != proto || inv_proto)) {
 		pr_info_ratelimited("%s_tables: %s match: only valid for protocol %u\n",
 				    xt_prefix[par->family], par->match->name,
 				    par->match->proto);
 		return -EINVAL;
 	}
 	if (par->match->checkentry != NULL) {
 		ret = par->match->checkentry(par);
 		if (ret < 0)
 			return ret;
 		else if (ret > 0)
 			/* Flag up potential errors. */
 			return -EIO;
 	}
 	return 0;
 }
 EXPORT_SYMBOL_GPL(xt_check_match);

 int xt_check_target(struct xt_tgchk_param *par,
 		    unsigned int size, u16 proto, bool inv_proto)
 {
 	int ret;

 	if (XT_ALIGN(par->target->targetsize) != size) {
 		pr_err_ratelimited("%s_tables: %s.%u target: invalid size %u (kernel) != (user) %u\n",
 				   xt_prefix[par->family], par->target->name,
 				   par->target->revision,
 				   XT_ALIGN(par->target->targetsize), size);
 		return -EINVAL;
 	}
 	if (par->target->table != NULL &&
 	    strcmp(par->target->table, par->table) != 0) {
 		pr_info_ratelimited("%s_tables: %s target: only valid in %s table, not %s\n",
 				    xt_prefix[par->family], par->target->name,
 				    par->target->table, par->table);
 		return -EINVAL;
 	}
+
+	/* NFPROTO_UNSPEC implies NF_INET_* hooks which do not overlap with
+	 * NF_ARP_IN,OUT,FORWARD, allow explicit extensions with NFPROTO_ARP
+	 * support.
+	 */
+	if (par->family == NFPROTO_ARP &&
+	    par->target->family != NFPROTO_ARP) {
+		pr_info_ratelimited("%s_tables: %s target: not valid for this family\n",
+				    xt_prefix[par->family], par->target->name);
+		return -EINVAL;
+	}
+
 	if (par->target->hooks && (par->hook_mask & ~par->target->hooks) != 0) {
 		char used[64], allow[64];

 		pr_info_ratelimited("%s_tables: %s target: used from hooks %s, but only usable from %s\n",
 				    xt_prefix[par->family], par->target->name,
 				    textify_hooks(used, sizeof(used),
 						  par->hook_mask, par->family),
 				    textify_hooks(allow, sizeof(allow),
 						  par->target->hooks,
 						  par->family));
 		return -EINVAL;
 	}
 	if (par->target->proto && (par->target->proto != proto || inv_proto)) {
 		pr_info_ratelimited("%s_tables: %s target: only valid for protocol %u\n",
 				    xt_prefix[par->family], par->target->name,
 				    par->target->proto);
 		return -EINVAL;
 	}
 	if (par->target->checkentry != NULL) {
 		ret = par->target->checkentry(par);
 		if (ret < 0)
 			return ret;
 		else if (ret > 0)
 			/* Flag up potential errors. */
 			return -EIO;
 	}
 	return 0;
 }
 EXPORT_SYMBOL_GPL(xt_check_target);


